"""CPU route geometry and CARLA-lazy controller for the unselected backing alternatives.

The route is a sequence of vehicle-center points in original Native coordinates.
It is an engineering construction: saved body history determines the outcome.
"""

import math

from shapely.affinity import rotate, translate
from shapely.geometry import MultiPoint, Polygon


def _point(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("Route point must have two coordinates")
    if any(type(item) not in (int, float) or not math.isfinite(item) for item in value):
        raise ValueError("Route point must be finite")
    return tuple(map(float, value))


def _angle(a, b):
    return math.degrees(math.atan2(b[1] - a[1], b[0] - a[0]))


def _delta(a, b):
    return (b - a + 180.0) % 360.0 - 180.0


def review_route(route_xy, start_body_xy, region_xy, *, alternative, expected_entry=True):
    """Check the planned complete-body sweep and the reverse turn geometry."""
    if alternative not in ("intersection", "street_corner"):
        raise ValueError("Unknown backing alternative")
    if not isinstance(route_xy, list) or len(route_xy) < 3:
        raise ValueError("Reverse route needs three or more points")
    route = [_point(row) for row in route_xy]
    if any(math.dist(a, b) < 0.15 for a, b in zip(route, route[1:])):
        raise ValueError("Reverse route has a degenerate segment")
    body = MultiPoint([_point(row) for row in start_body_xy]).convex_hull
    region = Polygon([_point(row) for row in region_xy])
    if body.area <= 0 or not region.is_valid or region.area <= 0:
        raise ValueError("Invalid vehicle body or sourced region")
    if body.intersects(region):
        raise ValueError("Reverse start body already occupies selected region")
    headings = [(_angle(a, b) + 180.0) % 360.0 for a, b in zip(route, route[1:])]
    cumulative_turn = sum(abs(_delta(a, b)) for a, b in zip(headings, headings[1:]))
    if any(abs(_delta(a, b)) > 15 for a, b in zip(headings, headings[1:])):
        raise ValueError("Reverse route has an abrupt steering corner")
    if alternative == "intersection" and cumulative_turn > 10:
        raise ValueError("Intersection construction must use a straight backing route")
    if alternative == "street_corner" and expected_entry and cumulative_turn < 30:
        raise ValueError("Street-corner construction lacks a planned turn")
    if not expected_entry and cumulative_turn > 10:
        raise ValueError("Stop-before construction turns before selected region")
    first_heading = headings[0]
    overlaps = []
    for index, center in enumerate(route):
        heading = headings[min(index, len(headings) - 1)]
        footprint = translate(rotate(body, _delta(first_heading, heading),
                                     origin=route[0], use_radians=False),
                              xoff=center[0] - route[0][0],
                              yoff=center[1] - route[0][1])
        overlaps.append(footprint.intersection(region).area)
    if expected_entry and not any(value > 0 for value in overlaps[1:]):
        raise ValueError("Planned reverse body never enters selected region")
    if not expected_entry and any(value > 0 for value in overlaps):
        raise ValueError("Stop-before body enters selected region")
    return {"alternative": alternative, "route_xy_m": [list(row) for row in route],
            "planned_body_region_overlap_area_m2": overlaps,
            "planned_heading_change_deg": _delta(headings[0], headings[-1]),
            "expected_entry": expected_entry,
            "actual_motion_confirmed": False}


class ReverseRouteController:
    """Follow a reviewed centerline while reversing; observed motion is audited later."""

    def __init__(self, route_xy, *, lookahead_m=2.0, wheelbase_m=2.7):
        if not isinstance(route_xy, list) or len(route_xy) < 3:
            raise ValueError("Reverse route needs three or more points")
        self.route = [_point(row) for row in route_xy]
        if lookahead_m <= 0 or wheelbase_m <= 0:
            raise ValueError("Positive lookahead and wheelbase required")
        self.lookahead = float(lookahead_m)
        self.wheelbase = float(wheelbase_m)

    def step(self, center_xy, heading_deg, speed_mps):
        center = _point(center_xy)
        if any(type(v) not in (int, float) or not math.isfinite(v)
               for v in (heading_deg, speed_mps)) or speed_mps < 0:
            raise ValueError("Finite heading and nonnegative speed required")
        nearest = min(range(len(self.route)),
                      key=lambda i: math.dist(center, self.route[i]))
        target = nearest
        while target < len(self.route) - 1 and math.dist(self.route[nearest], self.route[target]) < self.lookahead:
            target += 1
        aim = self.route[target]
        remaining = sum(math.dist(a, b) for a, b in zip(self.route[nearest:], self.route[nearest + 1:]))
        desired_heading = (_angle(center, aim) + 180.0) % 360.0
        error_rad = math.radians(_delta(float(heading_deg), desired_heading))
        # Negative longitudinal speed reverses the yaw response of steering.
        steer = max(-0.65, min(0.65, -math.atan2(2 * self.wheelbase *
                                                 math.sin(error_rad),
                                                 max(self.lookahead, math.dist(center, aim))) / 0.6))
        brake = remaining < 0.4 + speed_mps * speed_mps / 3.0
        return {"reverse": True, "throttle": 0.0 if brake else 0.16,
                "brake": 1.0 if brake else 0.0, "steer": steer,
                "route_index": nearest, "remaining_m": remaining,
                "target_reached": remaining < 0.4}

"""Native reverse request and readback for a source-reviewed approach."""
from contextlib import contextmanager
@contextmanager
def reverse_vehicle(world,vehicle,control_factory,*,throttle=0.2):
 if not 0<throttle<=0.4:raise ValueError('Conservative reverse throttle required')
 original=vehicle.get_control()
 try:
  vehicle.apply_control(control_factory(throttle=throttle,brake=0.0,reverse=True))
  world.tick()
  if vehicle.get_control().reverse is not True:raise ValueError('Native reverse readback failed')
  yield vehicle
 finally:
  vehicle.apply_control(original)
  world.tick()
  if vehicle.get_control().reverse!=original.reverse:raise ValueError('Vehicle control restoration failed')

"""Four original RGB source cameras for C215286 reverse construction."""
from contextlib import contextmanager

PROFILE = {'overview': (1920, 1080), 'approach': (1280, 720),
           'reference_corner': (1280, 720), 'driver_reference': (1280, 720)}


@contextmanager
def source_cameras(world, ego, transforms, plan):
    rows = {row['name']: row for row in plan}
    if set(rows) != set(PROFILE) or set(transforms) != set(PROFILE):
        raise ValueError('All four named source cameras required')
    sensors = {}
    try:
        for name, size in PROFILE.items():
            row = rows[name]
            if (row.get('width'), row.get('height')) != size:
                raise ValueError('Pinned source camera dimensions required')
            fov = row.get('fov_deg')
            if type(fov) not in (int, float) or not 30 <= fov <= 120:
                raise ValueError('Source camera FOV required')
            blueprint = world.get_blueprint_library().find('sensor.camera.rgb')
            for key, value in [('image_size_x', size[0]), ('image_size_y', size[1]),
                               ('fov', fov), ('sensor_tick', 0.05)]:
                blueprint.set_attribute(key, str(value))
            kwargs = {'attach_to': ego} if name == 'driver_reference' else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError('Native camera spawn failed: ' + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""Original-frame observations for the two remaining NRS 484B.113(2) alternatives.

This measures complete-body intersection occupation and reverse heading through
an authored corner region. Geometry and heading changes remain observations;
actual street-corner status and legal conclusions require source review.
"""

import hashlib
import json
import math
from pathlib import Path
from shapely.geometry import MultiPoint, Polygon

SOURCES = ("reverse_site_context.json", "reverse_history.jsonl", "video_frames.jsonl")


def _read(path):
    if not path.is_file():
        raise ValueError("Missing original source: " + path.name)
    raw = path.read_bytes()
    return raw.decode("utf-8"), hashlib.sha256(raw).hexdigest()


def _number(value, label):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError("Missing finite " + label)
    return float(value)


def _point(values, label):
    if not isinstance(values, (list, tuple)) or len(values) != 2:
        raise ValueError("Missing " + label)
    return tuple(_number(value, label) for value in values)


def _polygon(values, label):
    try:
        shape = Polygon([_point(value, label) for value in values])
    except (TypeError, ValueError) as error:
        raise ValueError("Invalid " + label) from error
    if not shape.is_valid or shape.area <= 0:
        raise ValueError("Invalid " + label)
    return shape


def _delta_degrees(start, end):
    return (end - start + 180.0) % 360.0 - 180.0


def analyze(root, alternative):
    if alternative not in ("intersection", "street_corner"):
        raise ValueError("Unknown NRS 484B.113(2) alternative")
    root = Path(root)
    originals = {name: _read(root / name) for name in SOURCES}
    source_text = {name: item[0] for name, item in originals.items()}
    hashes = {name: item[1] for name, item in originals.items()}
    context = json.loads(source_text["reverse_site_context.json"])
    if (context.get("alternative") != alternative
            or not context.get("native_map_id")
            or not context.get("geometry_source")
            or not context.get("camera_source")):
        raise ValueError("Incomplete source-identified reverse site")
    bindings = ["site_packet_source", "geometry_source", "camera_source"]
    if alternative == "street_corner":
        bindings.append("road_topology_source")
    for label in bindings:
        binding = context.get(label)
        if not isinstance(binding, dict) or not binding.get("path") or not binding.get("sha256"):
            raise ValueError("Missing original source binding: " + label)
        rel = Path(binding["path"])
        if rel.is_absolute() or ".." in rel.parts:
            raise ValueError("Unsafe original source path")
        _, digest = _read(root / rel)
        if digest != binding["sha256"]:
            raise ValueError("Changed original site source: " + label)
        hashes[str(rel)] = digest
    polygon_key = ("intersection_polygon_xy_m" if alternative == "intersection"
                   else "street_corner_region_xy_m")
    region = _polygon(context.get(polygon_key), polygon_key)
    histories = [json.loads(line) for line in source_text["reverse_history.jsonl"].splitlines()
                 if line.strip()]
    frames = [json.loads(line) for line in source_text["video_frames.jsonl"].splitlines()
              if line.strip()]
    if len(histories) < 3 or len(frames) != len(histories):
        raise ValueError("Incomplete original reverse frame joins")
    samples = []
    prior = None
    for index, (row, frame) in enumerate(zip(histories, frames)):
        fid = row.get("frame")
        time = _number(row.get("time_s"), "original time")
        if (type(fid) is not int or frame.get("video_frame") != index
                or frame.get("carla_frame") != fid or frame.get("time_s") != time):
            raise ValueError("Original reverse frame join differs")
        if prior and (fid != prior["frame"] + 1 or abs(time - prior["time_s"] - .05) > 1e-3):
            raise ValueError("Original reverse sequence is not continuous 20 Hz")
        vertices = row.get("ego_body_vertices_xy_m")
        if not isinstance(vertices, list) or len(vertices) < 4:
            raise ValueError("Missing original complete vehicle body")
        body = MultiPoint([_point(vertex, "body vertex") for vertex in vertices]).convex_hull
        if body.area <= 0:
            raise ValueError("Degenerate original vehicle body")
        if type(row.get("native_reverse")) is not bool:
            raise ValueError("Missing Native reverse readback")
        heading = _number(row.get("heading_deg"), "Native heading")
        center = (body.centroid.x, body.centroid.y)
        if prior:
            forward = (math.cos(math.radians(prior["heading_deg"])),
                       math.sin(math.radians(prior["heading_deg"])))
            step = ((center[0] - prior["center"][0]) * forward[0]
                    + (center[1] - prior["center"][1]) * forward[1])
            backward = prior["native_reverse"] and row["native_reverse"] and step < 0
            turn = _delta_degrees(prior["heading_deg"], heading)
        else:
            step, backward, turn = None, False, None
        sample = {"frame": fid, "time_s": time, "native_reverse": row["native_reverse"],
                  "backward_step_m": step, "backward_motion_observed": backward,
                  "body_intersects_region": body.intersects(region),
                  "body_region_overlap_area_m2": body.intersection(region).area,
                  "heading_deg": heading, "heading_change_deg": turn,
                  "body_center_xy_m": list(center)}
        samples.append(sample)
        prior = {"frame": fid, "time_s": time, "center": center,
                 "heading_deg": heading, "native_reverse": row["native_reverse"]}
    if samples[0]["body_intersects_region"]:
        raise ValueError("Reverse start body already occupies selected region")
    reverse = [sample for sample in samples if sample["backward_motion_observed"]]
    if not reverse:
        raise ValueError("No original backward body motion")
    result = {"format": "worker-reverse-alternatives-observations",
              "alternative": alternative, "source_sha256": hashes,
              "samples": samples, "backward_motion_observed": True,
              "reverse_body_enters_region": any(
                  sample["body_intersects_region"] for sample in reverse),
              "legal_conclusion": "unresolved pending original site and camera review"}
    if alternative == "street_corner":
        turning = [sample for sample in reverse
                   if sample["body_region_overlap_area_m2"] > 0
                   and sample["heading_change_deg"] is not None
                   and abs(sample["heading_change_deg"]) > 1e-6]
        runs = []
        run = []
        for sample in turning:
            if (run and (sample["frame"] != run[-1]["frame"] + 1
                         or sample["heading_change_deg"] * run[-1]["heading_change_deg"] <= 0)):
                runs.append(run)
                run = []
            run.append(sample)
        if run:
            runs.append(run)
        continuous = any(len(run) >= 3 and all(
            abs(sample["heading_change_deg"]) <= 15 for sample in run)
            for run in runs)
        result["reverse_heading_change_deg"] = _delta_degrees(
            samples[0]["heading_deg"], samples[-1]["heading_deg"])
        result["heading_change_while_in_corner_deg"] = sum(
            sample["heading_change_deg"] for sample in reverse
            if sample["body_region_overlap_area_m2"] > 0)
        result["continuous_reverse_turn_in_corner"] = continuous
    return result
